namespace RonSijm.FluidHumidifier.Factories.MGN;

public class LaunchConfigurationTemplateFactory(string resourceName = null, Action<Humidifier.MGN.LaunchConfigurationTemplate> factoryAction = null) : ResourceFactory<Humidifier.MGN.LaunchConfigurationTemplate>(resourceName)
{

    internal InnerLaunchConfigurationTemplateLaunchTemplateDiskConfFactory LargeVolumeConfFactory { get; set; }

    internal InnerLaunchConfigurationTemplateLaunchTemplateDiskConfFactory SmallVolumeConfFactory { get; set; }

    internal InnerLaunchConfigurationTemplateLicensingFactory LicensingFactory { get; set; }

    internal InnerLaunchConfigurationTemplatePostLaunchActionsFactory PostLaunchActionsFactory { get; set; }

    protected override Humidifier.MGN.LaunchConfigurationTemplate Create()
    {
        var launchConfigurationTemplateResult = CreateLaunchConfigurationTemplate();
        factoryAction?.Invoke(launchConfigurationTemplateResult);

        return launchConfigurationTemplateResult;
    }

    private Humidifier.MGN.LaunchConfigurationTemplate CreateLaunchConfigurationTemplate()
    {
        var launchConfigurationTemplateResult = new Humidifier.MGN.LaunchConfigurationTemplate
        {
            GivenName = InputResourceName,
        };

        return launchConfigurationTemplateResult;
    }
    public override void CreateChildren(Humidifier.MGN.LaunchConfigurationTemplate result)
    {
        base.CreateChildren(result);

        result.LargeVolumeConf ??= LargeVolumeConfFactory?.Build();
        result.SmallVolumeConf ??= SmallVolumeConfFactory?.Build();
        result.Licensing ??= LicensingFactory?.Build();
        result.PostLaunchActions ??= PostLaunchActionsFactory?.Build();
    }

} // End Of Class

